sp_widget.client_script:
api.controller = function($scope, $sce, spUtil, $rootScope, $window, $timeout) {
  var c = this;

  /* ---------- sidebar collapse sync (matches other pages) ---------- */
  c.isSidebarCollapsed = $window.localStorage.getItem('gatenow_sidebar_collapsed') === 'true';
  $rootScope.$on('sidebar.toggled', function(event, isCollapsed) {
    $timeout(function() { c.isSidebarCollapsed = isCollapsed; });
  });

  /* ---------- list state ---------- */
  c.activeFilter = 'all';
  c.detailTab    = 'overview';
  c.search       = '';

  c.setFilter    = function(f) { c.activeFilter = f; };
  c.setDetailTab = function(tab) { c.detailTab = tab; };

  c.filterFn = function(award) {
    if (c.activeFilter !== 'all' && award.applicant_response !== c.activeFilter) return false;
    var query = (c.search || '').toLowerCase().trim();
    if (!query) return true;
    return (award.program_name || '').toLowerCase().indexOf(query) > -1 ||
           (award.number || '').toLowerCase().indexOf(query) > -1;
  };

  c.countByResponse = function(status) {
    if (!c.data.awards) return 0;
    return c.data.awards.filter(function(a) { return a.applicant_response === status; }).length;
  };

  c.pendingAwards = function() {
    if (!c.data.awards) return [];
    return c.data.awards.filter(function(a) { return a.applicant_response === 'pending'; });
  };

  c.statusPct = function(status) {
    var total = (c.data.awards || []).length;
    return total > 0 ? Math.round((c.countByResponse(status) / total) * 100) : 0;
  };

  c.totalAmount = function() {
    if (!c.data.awards) return 0;
    return c.data.awards.reduce(function(s, a) { return s + (a.award_amount || 0); }, 0);
  };

  c.amountPercent = function(award) {
    var max = Math.max.apply(null, (c.data.awards || []).map(function(a) { return a.award_amount || 0; }));
    return max > 0 ? Math.round((award.award_amount / max) * 100) : 0;
  };

  /* ---------- detail ---------- */
  c.openAward = function(award, tab) {
    if (!award) return;
    award.award_letter = $sce.trustAsHtml(award.award_letter || '<p>No award letter content found.</p>');
    if (!award.decision_reason) award.decision_reason = 'No rationale provided.';
    c.detailTab = tab || 'overview';
    $scope.data.selectedAward = award;
    window.scrollTo(0, 0);
  };

  c.backToList = function() { $scope.data.selectedAward = null; };

  c.formatSize = function(bytes) {
    if (!bytes) return '—';
    if (bytes < 1024)    return bytes + ' B';
    if (bytes < 1048576) return (bytes / 1024).toFixed(1) + ' KB';
    return (bytes / 1048576).toFixed(1) + ' MB';
  };

  c.fileIcon = function(contentType) {
    if (!contentType) return 'fa-file-o';
    if (contentType.indexOf('pdf')   > -1) return 'fa-file-pdf-o';
    if (contentType.indexOf('image') > -1) return 'fa-file-image-o';
    if (contentType.indexOf('word')  > -1) return 'fa-file-word-o';
    if (contentType.indexOf('sheet') > -1 || contentType.indexOf('excel') > -1) return 'fa-file-excel-o';
    if (contentType.indexOf('zip')   > -1) return 'fa-file-archive-o';
    return 'fa-file-o';
  };

  c.updateChoice = function(award, statusValue) {
    c.data.action             = 'update_award_choice';
    c.data.target_id          = award.sys_id;
    c.data.new_status         = statusValue;
    c.data.comment_submission = award.work_notes;
    c.server.update().then(function() {
      award.applicant_response = statusValue.toLowerCase();
      award.work_notes = '';
      spUtil.addInfoMessage('Your response has been recorded.');
      c.backToList();
    });
  };
};

sp_widget.css:
/* =========================================================
   GATENOW · MY AWARDS
   Service Portal widget · CSS / SCSS

   Same design system as the Overview dashboard: Poppins,
   indigo #4457c9, weight-600 headings, the shared $gn-* tokens.
   Fully-expanded selectors only (the SP Sass compiler does not
   support parent-selector concatenation).
   ========================================================= */

.panel, .panel-body, .sp-widget { overflow: visible !important; }
.gn-layout { overflow: visible !important; }
.aw-sidebar {
  overflow-y: hidden !important;
  overflow-x: visible !important;
  overflow: visible !important;
  scrollbar-width: none;
  transition: all 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}
.aw-sidebar::-webkit-scrollbar { display: none; }

$gn-bg:          #f4f6fb;
$gn-card:        #ffffff;
$gn-line:        #e7eaf2;
$gn-line-soft:   #eff2f7;

$gn-ink:         #16203a;
$gn-ink-2:       #3f4a63;
$gn-muted:       #7b8598;
$gn-muted-2:     #9aa3b4;

$gn-indigo:      #4457c9;
$gn-indigo-dk:   #3a4bb3;
$gn-indigo-mid:  #7b90ee;
$gn-indigo-soft: #aebcf5;
$gn-violet:      #6f5fd0;
$gn-green:       #1f9d6d;
$gn-amber:       #e2a233;
$gn-red:         #e0525f;
$gn-slate:       #c9d2e3;

$gn-font: "Poppins", "Inter", "Segoe UI", -apple-system, BlinkMacSystemFont, Arial, sans-serif;

/* =========================================================
   SHELL
   ========================================================= */
.gn-dash {
  background: $gn-bg;
  font-family: $gn-font;
  color: $gn-ink;
  padding: 26px 30px 46px;
  min-height: 100vh;
}
.gn-dash *, .gn-dash *::before, .gn-dash *::after { box-sizing: border-box; }
.gn-dash h1, .gn-dash h2, .gn-dash h3, .gn-dash p { margin: 0; }
.gn-dash a { text-decoration: none; }
.gn-dash a:hover, .gn-dash a:focus { text-decoration: none; }
.gn-dash :focus-visible { outline: 2px solid $gn-indigo; outline-offset: 2px; }

/* =========================================================
   HEADER
   ========================================================= */
.gn-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 22px;
}
.gn-head__left { min-width: 0; }
.gn-head__title {
  font-size: 30px;
  font-weight: 600;
  letter-spacing: -0.6px;
  line-height: 1.15;
  color: $gn-ink;
}
.gn-head__meta {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 6px;
  font-size: 12.5px;
  color: $gn-muted;
}
.gn-head__right { display: flex; align-items: center; gap: 10px; flex-shrink: 0; }
.gn-live { width: 7px; height: 7px; border-radius: 50%; background: $gn-green; flex-shrink: 0; }

.gn-search {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 300px;
  height: 44px;
  padding: 0 15px;
  margin: 0;
  background: $gn-card;
  border: 1px solid $gn-line;
  border-radius: 12px;
  font-weight: 400;
}
.gn-search i { color: $gn-muted-2; font-size: 13px; }
.gn-search input { width: 100%; border: 0; outline: 0; background: transparent; font-size: 13.5px; color: $gn-ink-2; }
.gn-search input::placeholder { color: $gn-muted-2; }

.gn-avatar {
  width: 44px; height: 44px;
  border-radius: 12px;
  background: $gn-indigo;
  color: #ffffff;
  font-size: 13px; font-weight: 600; letter-spacing: 0.3px;
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
}

/* =========================================================
   KPI CARDS
   ========================================================= */
.gn-kpis {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 20px;
  margin-bottom: 20px;
}
@supports (grid-template-columns: repeat(auto-fit, minmax(220px, 1fr))) {
  .gn-kpis { grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); }
}
.gn-kpi {
  display: flex; flex-direction: column;
  background: $gn-card;
  border: 1px solid $gn-line;
  border-radius: 16px;
  padding: 20px 22px 16px;
  min-height: 186px;
  box-shadow: 0 1px 2px rgba(22, 32, 58, 0.04), 0 8px 20px rgba(22, 32, 58, 0.04);
}
.gn-kpi__top { display: flex; align-items: center; justify-content: space-between; }
.gn-kpi__label {
  font-size: 11.5px; font-weight: 600; letter-spacing: 0.8px;
  text-transform: uppercase; color: $gn-muted;
}
.gn-kpi__icon {
  width: 32px; height: 32px; border-radius: 9px;
  display: flex; align-items: center; justify-content: center;
  font-size: 13px; flex-shrink: 0;
}
.gn-kpi__icon--indigo { color: $gn-indigo; background: #edf1ff; }
.gn-kpi__icon--violet { color: $gn-violet; background: #f0edfd; }
.gn-kpi__icon--amber  { color: #c98a1c;    background: #fdf4e2; }
.gn-kpi__figure { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; margin-top: 14px; }
.gn-kpi__value {
  font-size: 38px; font-weight: 600; line-height: 1;
  letter-spacing: -1.4px; color: $gn-ink;
}
.gn-kpi__desc { margin-top: 10px; font-size: 12.5px; line-height: 1.55; color: $gn-muted; }
.gn-kpi__caption { margin-top: auto; padding-top: 10px; font-size: 11px; color: $gn-muted-2; }

/* ---------- chips ---------- */
.gn-chip {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 4px 10px; border-radius: 999px;
  font-size: 11.5px; font-weight: 500; white-space: nowrap;
  background: #f1f3f8; color: $gn-ink-2;
}
.gn-chip--green { background: #e6f6ef; color: #178a5e; }
.gn-chip--amber { background: #fdf1dd; color: #b9801a; }
.gn-chip--red   { background: #fdecee; color: #cf4351; }

/* =========================================================
   CARD SYSTEM
   ========================================================= */
.gn-row { display: grid; gap: 20px; margin-bottom: 20px; }
.gn-row--wide { grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr); }
.gn-row--half { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }

.gn-card {
  display: flex; flex-direction: column;
  background: $gn-card;
  border: 1px solid $gn-line;
  border-radius: 16px;
  box-shadow: 0 1px 2px rgba(22, 32, 58, 0.04), 0 8px 20px rgba(22, 32, 58, 0.04);
  min-width: 0; overflow: hidden;
}
.gn-card__head {
  display: flex; align-items: flex-start; justify-content: space-between;
  gap: 16px; padding: 20px 24px 4px;
}
.gn-card__head h2 { font-size: 17px; font-weight: 600; letter-spacing: -0.2px; line-height: 1.3; color: $gn-ink; }
.gn-card__head p { margin-top: 4px; font-size: 12.5px; color: $gn-muted; }
.gn-card__body { padding: 18px 24px 22px; flex: 1; }

.gn-empty { padding: 34px 12px; text-align: center; font-size: 12.5px; line-height: 1.6; color: $gn-muted-2; }
.gn-empty--block {
  background: $gn-card; border: 1px solid $gn-line; border-radius: 16px;
  box-shadow: 0 1px 2px rgba(22, 32, 58, 0.04), 0 8px 20px rgba(22, 32, 58, 0.04);
}

/* ---------- health / legend / project list ---------- */
.gn-health {
  display: flex; height: 46px; border-radius: 12px; overflow: hidden;
  background: #eef1f6; color: #ffffff; font-size: 13px; font-weight: 500;
}
.gn-health__seg {
  display: flex; align-items: center; justify-content: center;
  min-width: 42px; white-space: nowrap; transition: width 0.45s ease;
}
.gn-health__seg--green { background: #1f9d6d; }
.gn-health__seg--amber { background: #dfa227; }
.gn-health__seg--red   { background: $gn-red; }
.gn-health__rest {
  flex: 0 0 auto; min-width: 52px; padding: 0 14px;
  display: flex; align-items: center; justify-content: center;
  color: $gn-muted; font-size: 12.5px;
}
.gn-legend {
  display: flex; flex-wrap: wrap; gap: 8px; margin-top: 14px;
  padding-bottom: 18px; border-bottom: 1px solid $gn-line-soft;
}
.gn-legend__pill {
  display: inline-flex; align-items: center; gap: 7px;
  padding: 5px 11px; border-radius: 999px; background: #f4f6fa;
  font-size: 12px; color: $gn-ink-2;
}
.gn-dot { display: inline-block; width: 7px; height: 7px; border-radius: 50%; flex-shrink: 0; background: $gn-slate; }
.gn-dot--green { background: $gn-green; }
.gn-dot--amber { background: $gn-amber; }
.gn-dot--red   { background: $gn-red; }

.gn-projects { padding-top: 6px; }
.gn-project {
  display: grid; grid-template-columns: minmax(0, 1fr) auto;
  align-items: center; gap: 6px 12px; padding: 12px 0;
  border-bottom: 1px solid $gn-line-soft;
}
.gn-project:last-child { border-bottom: 0; }
.gn-project__name { display: flex; align-items: center; gap: 9px; min-width: 0; font-size: 13.5px; font-weight: 500; color: $gn-ink; }
.gn-project__name span { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.gn-project__pct { font-size: 13px; font-weight: 500; color: $gn-ink-2; }

/* ---------- program-style list (needs response) ---------- */
.gn-program {
  display: block; padding: 14px 16px; margin-bottom: 12px;
  border: 1px solid $gn-line; border-radius: 12px; color: inherit;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.gn-program:last-child { margin-bottom: 0; }
.gn-program:hover { border-color: $gn-indigo-soft; box-shadow: 0 6px 16px rgba(22, 32, 58, 0.06); }
.gn-program__top { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; }
.gn-program__top strong { font-size: 14px; font-weight: 600; color: $gn-ink; }
.gn-program__foot { margin-top: 10px; font-size: 12px; color: $gn-muted; }
.gn-program__foot i { margin-right: 4px; }

/* ---------- state pills ---------- */
.gn-state {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 5px 11px; border-radius: 999px;
  background: #f2f4f8; color: $gn-ink-2;
  font-size: 11.5px; font-weight: 500; white-space: nowrap;
}
.gn-state--red   { background: #fdecee; color: #cf4351; }
.gn-state--amber { background: #fdf3e0; color: #b9801a; }
.gn-state--green { background: #e6f6ef; color: #178a5e; }
.gn-state--red .gn-dot   { background: $gn-red; }
.gn-state--amber .gn-dot { background: $gn-amber; }
.gn-state--green .gn-dot { background: $gn-green; }

/* ---------- tag ---------- */
.gn-tag {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 4px 10px; border-radius: 7px;
  background: #edf1ff; color: $gn-indigo;
  font-size: 11.5px; font-weight: 500; white-space: nowrap;
}

/* ---------- buttons ---------- */
.gn-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 7px;
  min-width: 74px; height: 36px; padding: 0 16px;
  border: 1px solid $gn-line; border-radius: 9px;
  background: $gn-card; color: $gn-ink-2;
  font-family: $gn-font; font-size: 12.5px; font-weight: 500;
  cursor: pointer;
}
.gn-btn:hover { border-color: $gn-indigo-soft; color: $gn-indigo; }
.gn-btn--primary { background: $gn-indigo; border-color: $gn-indigo; color: #ffffff; }
.gn-btn--primary:hover { background: $gn-indigo-dk; border-color: $gn-indigo-dk; color: #ffffff; }
.gn-btn--danger { background: $gn-red; border-color: $gn-red; color: #ffffff; }
.gn-btn--danger:hover { background: #cf4351; border-color: #cf4351; color: #ffffff; }

/* =========================================================
   AWARD LIST · filter tabs
   ========================================================= */
.aw-tabs { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 18px; }
.aw-tab {
  display: inline-flex; align-items: center; gap: 8px;
  height: 38px; padding: 0 16px;
  border: 1px solid $gn-line; border-radius: 999px;
  background: $gn-card; color: $gn-muted;
  font-family: $gn-font; font-size: 13px; font-weight: 500;
  cursor: pointer; transition: border-color 0.15s, color 0.15s, background 0.15s;
}
.aw-tab:hover { border-color: $gn-indigo-soft; color: $gn-ink-2; }
.aw-tab--active { background: $gn-indigo; border-color: $gn-indigo; color: #ffffff; }
.aw-tab__n { font-size: 11.5px; font-weight: 600; color: $gn-muted-2; }
.aw-tab--active .aw-tab__n { color: rgba(255, 255, 255, 0.85); }

/* =========================================================
   AWARD LIST · cards
   ========================================================= */
.aw-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(330px, 1fr));
  gap: 20px;
}
.aw-card {
  display: flex; flex-direction: column;
  background: $gn-card;
  border: 1px solid $gn-line;
  border-radius: 16px;
  padding: 20px 22px 18px;
  box-shadow: 0 1px 2px rgba(22, 32, 58, 0.04), 0 8px 20px rgba(22, 32, 58, 0.04);
  cursor: pointer;
  transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
}
.aw-card:hover { border-color: $gn-indigo-soft; box-shadow: 0 12px 24px rgba(22, 32, 58, 0.10); transform: translateY(-2px); }
.aw-card__top { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 14px; }
.aw-card__num { font-size: 12.5px; font-weight: 500; color: $gn-muted-2; }
.aw-card__title { font-size: 16px; font-weight: 600; letter-spacing: -0.2px; line-height: 1.35; color: $gn-ink; }
.aw-card__tag {
  display: inline-flex; align-items: center; gap: 6px; margin-top: 10px;
  font-size: 12px; color: $gn-indigo; font-weight: 500;
}
.aw-card__amount {
  display: flex; align-items: baseline; justify-content: space-between;
  gap: 10px; margin-top: 18px;
}
.aw-card__amount-lbl { font-size: 12.5px; color: $gn-muted; }
.aw-card__amount-val { font-size: 20px; font-weight: 600; letter-spacing: -0.4px; color: $gn-ink; }
.aw-card__bar { height: 6px; margin-top: 10px; border-radius: 999px; background: #edf0f6; overflow: hidden; }
.aw-card__bar-fill { height: 100%; border-radius: 999px; background: $gn-indigo; transition: width 0.45s ease; }

.aw-card__dates {
  display: flex; align-items: center; gap: 12px;
  margin-top: 18px; padding-top: 16px;
  border-top: 1px solid $gn-line-soft;
}
.aw-card__date { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.aw-card__date--end { text-align: right; margin-left: auto; }
.aw-card__date-lbl { font-size: 10.5px; font-weight: 600; letter-spacing: 0.6px; text-transform: uppercase; color: $gn-muted-2; }
.aw-card__date-val { font-size: 13px; font-weight: 500; color: $gn-ink-2; }
.aw-card__arrow { color: $gn-muted-2; font-size: 13px; }

.aw-card__foot {
  display: flex; align-items: center; justify-content: space-between;
  gap: 12px; margin-top: 18px;
}
.aw-card__alert {
  display: inline-flex; align-items: center; gap: 8px;
  font-size: 12px; font-weight: 500; color: #b9801a;
}
.aw-pulse {
  width: 8px; height: 8px; border-radius: 50%; background: $gn-amber;
  box-shadow: 0 0 0 0 rgba(226, 162, 51, 0.5);
  animation: awPulse 1.8s infinite;
}
@keyframes awPulse {
  0%   { box-shadow: 0 0 0 0 rgba(226, 162, 51, 0.5); }
  70%  { box-shadow: 0 0 0 7px rgba(226, 162, 51, 0); }
  100% { box-shadow: 0 0 0 0 rgba(226, 162, 51, 0); }
}

/* ---------- empty state ---------- */
.aw-empty {
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  padding: 72px 20px; text-align: center;
  background: $gn-card; border: 1px solid $gn-line; border-radius: 16px;
  box-shadow: 0 1px 2px rgba(22, 32, 58, 0.04), 0 8px 20px rgba(22, 32, 58, 0.04);
}
.aw-empty__icon {
  width: 60px; height: 60px; border-radius: 16px;
  display: flex; align-items: center; justify-content: center;
  background: #edf1ff; color: $gn-indigo; font-size: 26px; margin-bottom: 18px;
}
.aw-empty h2 { font-size: 19px; font-weight: 600; color: $gn-ink; margin-bottom: 8px; }
.aw-empty p { font-size: 13px; line-height: 1.6; color: $gn-muted; }

/* =========================================================
   DETAIL · back bar
   ========================================================= */
.dt-bar {
  display: flex; align-items: center; gap: 16px;
  margin-bottom: 20px; flex-wrap: wrap;
}
.dt-crumb {
  display: flex; align-items: center; gap: 8px;
  font-size: 13px; color: $gn-muted; min-width: 0;
}
.dt-crumb__prog { color: $gn-ink-2; font-weight: 500; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.dt-crumb__sep { color: $gn-muted-2; }
.dt-crumb__num { color: $gn-muted; }
.dt-bar .gn-state { margin-left: auto; }

/* =========================================================
   DETAIL · hero
   ========================================================= */
.dt-hero { flex-direction: row; align-items: stretch; gap: 24px; padding: 26px 28px; }
.dt-hero__id { flex: 1; min-width: 0; }
.dt-hero__eyebrow {
  display: inline-flex; align-items: center; gap: 7px;
  font-size: 11.5px; font-weight: 600; letter-spacing: 0.7px; text-transform: uppercase;
  color: $gn-indigo;
}
.dt-hero__title { margin-top: 8px; font-size: 30px; font-weight: 600; letter-spacing: -0.8px; color: $gn-ink; }
.dt-hero__sub { margin-top: 4px; font-size: 15px; color: $gn-ink-2; }
.dt-hero__tags { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 14px; }
.dt-amount {
  flex: 0 0 260px;
  background: #f7f8fd; border: 1px solid $gn-line-soft; border-radius: 14px;
  padding: 18px 20px;
}
.dt-amount__lbl { font-size: 11.5px; font-weight: 600; letter-spacing: 0.7px; text-transform: uppercase; color: $gn-muted; }
.dt-amount__val { margin-top: 8px; font-size: 26px; font-weight: 600; letter-spacing: -0.8px; color: $gn-ink; }
.dt-amount__bar { height: 7px; margin-top: 14px; border-radius: 999px; background: #e4e8f3; overflow: hidden; }
.dt-amount__fill { height: 100%; border-radius: 999px; background: $gn-indigo; transition: width 0.45s ease; }
.dt-amount__note { margin-top: 8px; font-size: 11px; color: $gn-muted-2; }

/* =========================================================
   DETAIL · timeline
   ========================================================= */
.dt-tlcard { padding: 20px 28px; }
.dt-tl { display: flex; align-items: center; gap: 14px; }
.dt-tl__node { display: flex; align-items: center; gap: 12px; min-width: 0; }
.dt-tl__dot {
  width: 38px; height: 38px; border-radius: 11px; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  font-size: 14px; color: #ffffff;
}
.dt-tl__dot--start { background: $gn-indigo; }
.dt-tl__dot--eff   { background: $gn-violet; }
.dt-tl__dot--end   { background: $gn-green; }
.dt-tl__info { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.dt-tl__lbl { font-size: 10.5px; font-weight: 600; letter-spacing: 0.6px; text-transform: uppercase; color: $gn-muted-2; }
.dt-tl__val { font-size: 13.5px; font-weight: 500; color: $gn-ink; }
.dt-tl__line { flex: 1; height: 2px; border-radius: 2px; background: $gn-line; min-width: 20px; }
.dt-tl--stack { flex-direction: column; align-items: stretch; gap: 0; }
.dt-tl--stack .dt-tl__node { padding: 6px 0; }
.dt-tl__line--v { flex: 0 0 auto; width: 2px; height: 16px; margin-left: 18px; }

/* =========================================================
   DETAIL · tabs
   ========================================================= */
.dt-tabs {
  display: flex; flex-wrap: wrap; gap: 6px;
  margin-bottom: 20px; padding-bottom: 4px;
  border-bottom: 1px solid $gn-line;
}
.dt-tab {
  display: inline-flex; align-items: center; gap: 8px;
  height: 40px; padding: 0 16px;
  border: 0; border-bottom: 2px solid transparent;
  background: none; color: $gn-muted;
  font-family: $gn-font; font-size: 13px; font-weight: 500;
  cursor: pointer; transition: color 0.15s;
}
.dt-tab:hover { color: $gn-ink-2; }
.dt-tab--active { color: $gn-indigo; border-bottom-color: $gn-indigo; }
.dt-tab__n {
  padding: 1px 7px; border-radius: 999px;
  background: #edf1ff; color: $gn-indigo; font-size: 11px; font-weight: 600;
}
.dt-tab--amber { color: #b9801a; }
.dt-tab--amber.dt-tab--active { color: #b9801a; border-bottom-color: $gn-amber; }

/* =========================================================
   DETAIL · fields / quote
   ========================================================= */
.dt-fields { display: flex; flex-direction: column; }
.dt-field {
  display: flex; align-items: baseline; justify-content: space-between;
  gap: 16px; padding: 11px 0; border-bottom: 1px solid $gn-line-soft;
}
.dt-field:last-child { border-bottom: 0; }
.dt-field__lbl { font-size: 12.5px; color: $gn-muted; }
.dt-field__val { font-size: 13px; font-weight: 500; color: $gn-ink; text-align: right; word-break: break-word; }
.dt-field__val--brand { color: $gn-indigo; }
.dt-field__val--green { color: #178a5e; }

.dt-quote {
  position: relative; margin: 0; padding: 4px 0 4px 18px;
  border-left: 3px solid $gn-indigo-soft;
  font-size: 13.5px; line-height: 1.65; color: $gn-ink-2;
}

/* =========================================================
   DETAIL · financial hero
   ========================================================= */
.dt-fin__body { display: flex; align-items: center; gap: 28px; flex-wrap: wrap; }
.dt-fin__left { flex: 1; min-width: 220px; }
.dt-fin__big { margin-top: 8px; font-size: 34px; font-weight: 600; letter-spacing: -1px; color: $gn-ink; }
.dt-fin__cap { margin-top: 6px; font-size: 12.5px; color: $gn-muted; }
.dt-fin__right { flex: 1; min-width: 220px; }
.dt-fin__barlbl { display: flex; align-items: center; justify-content: space-between; margin-bottom: 8px; font-size: 12.5px; color: $gn-ink-2; }

/* =========================================================
   DETAIL · award letter
   ========================================================= */
.dt-letter { font-size: 13.5px; line-height: 1.7; color: $gn-ink-2; }
.dt-letter p { margin: 0 0 12px; }
.dt-letter h1, .dt-letter h2, .dt-letter h3 { color: $gn-ink; font-weight: 600; margin: 18px 0 8px; }

/* =========================================================
   DETAIL · attachments
   ========================================================= */
.dt-att {
  display: flex; align-items: center; gap: 14px;
  padding: 13px 14px; margin-bottom: 10px;
  border: 1px solid $gn-line; border-radius: 12px;
  color: inherit; transition: border-color 0.2s, box-shadow 0.2s;
}
.dt-att:last-child { margin-bottom: 0; }
.dt-att:hover { border-color: $gn-indigo-soft; box-shadow: 0 6px 16px rgba(22, 32, 58, 0.06); }
.dt-att__ico {
  width: 40px; height: 40px; border-radius: 10px; flex-shrink: 0;
  display: flex; align-items: center; justify-content: center;
  background: #edf1ff; color: $gn-indigo; font-size: 16px;
}
.dt-att__meta { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.dt-att__name { font-size: 13.5px; font-weight: 500; color: $gn-ink; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.dt-att__info { font-size: 11.5px; color: $gn-muted; }
.dt-att__dl { flex-shrink: 0; display: inline-flex; align-items: center; gap: 6px; font-size: 12.5px; font-weight: 500; color: $gn-indigo; }

.dt-att-empty { padding: 40px 12px; text-align: center; }
.dt-att-empty__icon {
  width: 56px; height: 56px; border-radius: 14px; margin: 0 auto 16px;
  display: flex; align-items: center; justify-content: center;
  background: $gn-line-soft; color: $gn-muted-2; font-size: 22px;
}
.dt-att-empty__title { font-size: 14px; font-weight: 600; color: $gn-ink; }
.dt-att-empty__sub { margin-top: 4px; font-size: 12.5px; color: $gn-muted; }

/* =========================================================
   DETAIL · respond
   ========================================================= */
.dt-alert {
  display: flex; align-items: flex-start; gap: 14px;
  padding: 16px 18px; margin-bottom: 20px;
  background: #fdf6e8; border: 1px solid #f4e2bd; border-radius: 14px;
}
.dt-alert__ico { color: $gn-amber; font-size: 17px; margin-top: 1px; }
.dt-alert__title { font-size: 13.5px; font-weight: 600; color: #9a6b16; }
.dt-alert__sub { margin-top: 3px; font-size: 12.5px; line-height: 1.55; color: #b0842e; }

.dt-recap {
  display: flex; flex-wrap: wrap; gap: 12px;
  padding: 14px 16px; margin-bottom: 20px;
  background: #f7f8fd; border: 1px solid $gn-line-soft; border-radius: 12px;
}
.dt-recap__f { display: flex; flex-direction: column; gap: 4px; min-width: 120px; flex: 1; }
.dt-recap__l { font-size: 10.5px; font-weight: 600; letter-spacing: 0.6px; text-transform: uppercase; color: $gn-muted-2; }
.dt-recap__v { font-size: 13.5px; font-weight: 500; color: $gn-ink; }
.dt-recap__v--green { color: #178a5e; }

.dt-resp__hdr { display: flex; align-items: center; justify-content: space-between; margin-bottom: 8px; }
.dt-resp__lbl { font-size: 13px; font-weight: 500; color: $gn-ink; }
.dt-req { color: $gn-red; }
.dt-resp__count { font-size: 11.5px; font-weight: 500; }
.dt-resp__count--low { color: $gn-amber; }
.dt-resp__count--ok { color: $gn-muted-2; }
.dt-resp__ta {
  width: 100%; padding: 13px 14px;
  border: 1px solid $gn-line; border-radius: 12px;
  background: $gn-card; color: $gn-ink;
  font-family: $gn-font; font-size: 13.5px; line-height: 1.6; resize: vertical;
}
.dt-resp__ta:focus { outline: none; border-color: $gn-indigo; box-shadow: 0 0 0 3px rgba(68, 87, 201, 0.1); }
.dt-resp__ta::placeholder { color: $gn-muted-2; }
.dt-resp__hint { display: flex; align-items: center; gap: 7px; margin-top: 10px; font-size: 12px; color: $gn-muted; }
.dt-resp__actions { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 20px; }
.dt-resp__actions .gn-btn { height: 42px; min-width: 150px; font-size: 13.5px; }

.dt-responded { display: flex; flex-direction: column; align-items: center; text-align: center; padding: 40px 20px; }
.dt-responded__icon {
  width: 60px; height: 60px; border-radius: 50%; margin-bottom: 18px;
  display: flex; align-items: center; justify-content: center; font-size: 24px;
  background: #eef1f6; color: $gn-muted;
}
.dt-responded__icon--green { background: #e6f6ef; color: #178a5e; }
.dt-responded__icon--red { background: #fdecee; color: #cf4351; }
.dt-responded__title { font-size: 17px; font-weight: 600; color: $gn-ink; }
.dt-responded__sub { margin-top: 6px; font-size: 13px; color: $gn-muted; }
.dt-responded__sub strong { color: $gn-ink-2; text-transform: lowercase; }

/* =========================================================
   RESPONSIVE
   ========================================================= */
@media (max-width: 1024px) {
  .gn-kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .gn-row--wide, .gn-row--half { grid-template-columns: minmax(0, 1fr); }
  .dt-hero { flex-direction: column; }
  .dt-amount { flex: 1 1 auto; }
}
@media (max-width: 900px) {
  .gn-dash { padding: 20px 16px 36px; }
  .gn-head { flex-direction: column; align-items: stretch; }
  .gn-head__right { flex-wrap: wrap; }
  .gn-search { width: 100%; flex: 1 1 200px; }
  .aw-list { grid-template-columns: 1fr; }
  .dt-tl { flex-direction: column; align-items: stretch; gap: 0; }
  .dt-tl__node { padding: 8px 0; }
  .dt-tl__line { width: 2px; height: 16px; margin-left: 18px; flex: 0 0 auto; }
}
@media (max-width: 620px) {
  .gn-kpis { grid-template-columns: minmax(0, 1fr); }
  .gn-head__title { font-size: 25px; }
  .dt-resp__actions .gn-btn { width: 100%; }
}
@media (prefers-reduced-motion: reduce) {
  .gn-dash *, .aw-card, .aw-pulse { transition: none; animation: none; }
}

sp_widget.script:
(function() {

  /* =========================================================
     GATENOW · MY AWARDS · Server script

     Awards are constrained to the signed-in user's applicant
     record(s). The ownership condition (applicant.user =
     currentUser) is the PRIMARY query term, so the list can
     never fall through to every award. The response update
     re-verifies ownership before writing.
     ========================================================= */

  var AWARDS    = 'x_enno_gatenow_grant_awards';
  var APPLICANT = 'x_enno_gatenow_service_applicants';

  data.sideBar       = $sp.getWidget('sidebar_dashboard');
  data.awards        = [];
  data.selectedAward = null;

  var currentUser = gs.getUserID();

  /* ---------- header monogram (scoped-safe) ---------- */
  var gu = gs.getUser();
  data.userName = gu.getDisplayName() || '';
  var fn = gu.getFirstName() || '', ln = gu.getLastName() || '';
  data.userInitials = ((fn.charAt(0) || '') + (ln.charAt(0) || '')).toUpperCase();

  /* ---------- 1 · applicant records for this user ---------- */
  var applicantIds = [];
  var appGR = new GlideRecordSecure(APPLICANT);
  appGR.addQuery('user', currentUser);
  appGR.query();
  while (appGR.next()) applicantIds.push(appGR.getUniqueValue());

  /* ---------- 2 · handle response update (ownership re-checked) ---------- */
  if (input && input.action === 'update_award_choice' && input.target_id) {
    var upGR = new GlideRecordSecure(AWARDS);
    upGR.addQuery('sys_id', input.target_id);
    upGR.addQuery('applicant.user', currentUser);   // only your own award
    upGR.query();
    if (upGR.next()) {
      upGR.setValue('applicant_response', input.new_status);
      if (input.comment_submission) upGR.work_notes = input.comment_submission;
      upGR.update();
    }
  }

  /* ---------- 3 · fetch this user's awards ---------- */
  var awGR = new GlideRecordSecure(AWARDS);
  var q = awGR.addQuery('applicant.user', currentUser);            // guaranteed constraint
  if (applicantIds.length) q.addOrCondition('applicant', 'IN', applicantIds.join(','));
  awGR.orderByDesc('sys_created_on');
  awGR.query();

  while (awGR.next()) {
    var id = awGR.getUniqueValue();

    var attachments = [];
    var at = new GlideRecordSecure('sys_attachment');
    at.addQuery('table_name', AWARDS);
    at.addQuery('table_sys_id', id);
    at.query();
    while (at.next()) {
      attachments.push({
        sys_id:        at.getUniqueValue(),
        file_name:     at.getDisplayValue('file_name'),
        content_type:  at.getDisplayValue('content_type'),
        size_bytes:    parseInt(at.getValue('size_bytes') || 0, 10),
        download_link: '/sys_attachment.do?sys_id=' + at.getUniqueValue()
      });
    }

    data.awards.push({
      sys_id:                     id,
      number:                     awGR.getDisplayValue('number'),
      program_name:               awGR.getDisplayValue('program_name'),
      proposal_number:            awGR.getDisplayValue('applicant'),
      effective_date_of_award:    awGR.getDisplayValue('effective_date_of_award'),
      award_start_date:           awGR.getDisplayValue('award_start_date'),
      award_end_date:             awGR.getDisplayValue('award_end_date'),
      award_amount:               parseFloat(awGR.getValue('build_grant_amount') || 0),
      applicant_response:         normalizeResponse(awGR.getValue('applicant_response')),
      applicant_response_display: awGR.getDisplayValue('applicant_response') || 'Pending',
      grant_program_id:           awGR.getDisplayValue('grant_program'),
      decision_reason:            awGR.getDisplayValue('decision_reason'),
      award_letter:               awGR.getValue('award_letter'),
      fain:                       awGR.getDisplayValue('fain'),
      assistance_listing:         awGR.getDisplayValue('assistance_listing'),
      unique_entity_id:           awGR.getDisplayValue('unique_entity_id'),
      tin:                        awGR.getDisplayValue('tin'),
      funding_opportunity_number: awGR.getDisplayValue('funding_opportunity_number'),
      procurement_request_number: awGR.getDisplayValue('procurement_request_number'),
      attachments:                attachments,
      work_notes:                 ''
    });
  }

  /* one canonical set of status values: acknowledged | pending | declined */
  function normalizeResponse(raw) {
    var v = String(raw || '').toLowerCase();
    if (v.indexOf('ack') > -1) return 'acknowledged';
    if (v.indexOf('declin') > -1 || v.indexOf('reject') > -1) return 'declined';
    return 'pending';
  }

})();
